import os
import pandas as pd
import numpy as np
import unicodedata
from sklearn.linear_model import LinearRegression

# ==============================================================================
# CONFIGURATION
# ==============================================================================
# Mettez ici le chemin du dossier contenant TOUS vos fichiers Excel/CSV
DATA_FOLDER = (
    r"C:\Users\gabri\OneDrive - Groupe INSEEC (POCE)\ING5\S1\PFE\CSV\OWUFolder"
)


class Tools:
    def __init__(self):
        pass

    # ==============================================================================
    # HELPER : Normalisation pour éviter les erreurs d'apostrophes/accents
    # ==============================================================================
    def _smart_normalize(self, text: str) -> str:
        """Nettoie le texte : minuscules, apostrophes courbes -> droites, sans accents."""
        if not isinstance(text, str):
            return str(text)
        text = text.lower().strip()
        # Harmonisation des guillemets et apostrophes
        text = text.replace("’", "'").replace("“", '"').replace("”", '"')
        # Suppression des accents (ex: "Dépenses" -> "depenses")
        text = "".join(
            c
            for c in unicodedata.normalize("NFD", text)
            if unicodedata.category(c) != "Mn"
        )
        return text

    # ==============================================================================
    # 1. EXPLORATION DE BASE
    # ==============================================================================
    def list_available_datasets(self) -> dict:
        """Liste les fichiers disponibles."""
        if not os.path.exists(DATA_FOLDER):
            return {"error": f"Le dossier {DATA_FOLDER} n'existe pas."}
        files = [
            f for f in os.listdir(DATA_FOLDER) if f.endswith((".csv", ".xlsx", ".xls"))
        ]
        return {
            "count": len(files),
            "files": files,
            "message": "Fichiers trouvés. Utilise 'inspect_dataset_structure' pour en lire un.",
        }

    def inspect_dataset_structure(self, filename: str) -> dict:
        """Aperçu des colonnes et 3 premières lignes."""
        path = os.path.join(DATA_FOLDER, filename)
        if not os.path.exists(path):
            return {"error": "Fichier introuvable."}
        try:
            if filename.endswith(".csv"):
                try:
                    df = pd.read_csv(path, sep=None, engine="python", nrows=5)
                except:
                    df = pd.read_csv(path, sep=";", nrows=5)
            else:
                df = pd.read_excel(path, nrows=5)

            clean_cols = [str(c).strip() for c in df.columns]
            return {
                "filename": filename,
                "columns": clean_cols,
                "preview": df.head(3).to_dict(orient="records"),
            }
        except Exception as e:
            return {"error": f"Erreur lecture: {str(e)}"}

    # ==============================================================================
    # 2. CALCULATRICE SIMPLE
    # ==============================================================================
    def analyze_generic_metric(self, filename: str, column_keyword: str) -> dict:
        """Stats de base (Somme, Moyenne) sur une colonne spécifique."""
        path = os.path.join(DATA_FOLDER, filename)
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except:
            return {"error": "Erreur lecture fichier."}

        # Recherche floue de la colonne
        df_cols_map = {self._smart_normalize(c): c for c in df.columns}
        search_key = self._smart_normalize(column_keyword)
        target = next(
            (real for clean, real in df_cols_map.items() if search_key in clean), None
        )

        if not target:
            return {
                "error": f"Colonne contenant '{column_keyword}' introuvable.",
                "available": list(df.columns),
            }

        try:
            series = pd.to_numeric(df[target], errors="coerce").dropna()
            if series.empty:
                return {"error": "Colonne vide ou non numérique."}
            return {
                "metric_name": target,
                "sum": series.sum(),
                "mean": series.mean(),
                "min": series.min(),
                "max": series.max(),
                "count": len(series),
            }
        except:
            return {"error": "Erreur calcul statistique."}

    # ==============================================================================
    # 3. ANALYSE PARETO (Compatible Wide Format / Fichier Transposé)
    # ==============================================================================
    def analyze_pareto_distribution(
        self, filename: str, filter_keyword: str = "Dépenses"
    ) -> dict:
        """
        Identifie les colonnes qui pèsent le plus lourd (Top 5).
        Args:
            filter_keyword: Mot-clé pour filtrer les colonnes (ex: 'Dépenses', 'Recettes').
        """
        path = os.path.join(DATA_FOLDER, filename)
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except:
            return {"error": "Erreur lecture fichier."}

        keyword_norm = self._smart_normalize(filter_keyword)
        relevant_cols = []

        # On scanne toutes les colonnes pour voir si elles contiennent le mot clé
        for c in df.columns:
            c_norm = self._smart_normalize(c)
            # On exclut ce qui contient "total" pour éviter les doublons de comptabilité
            if keyword_norm in c_norm and "total" not in c_norm:
                # On vérifie qu'il y a bien des chiffres
                if pd.to_numeric(df[c], errors="coerce").notna().sum() > 0:
                    relevant_cols.append(c)

        if not relevant_cols:
            return {
                "error": f"Aucune colonne trouvée contenant '{filter_keyword}' (hors Total).",
                "hint": "Essaie avec un mot générique comme 'Recettes' ou 'Dépenses'.",
            }

        # Calcul des sommes
        df[relevant_cols] = (
            df[relevant_cols].apply(pd.to_numeric, errors="coerce").fillna(0)
        )
        sums = df[relevant_cols].sum().sort_values(ascending=False)
        total_global = sums.sum()

        top_5 = sums.head(5)
        results = []
        for col_name, val in top_5.items():
            perc = (val / total_global) * 100 if total_global != 0 else 0
            # Nettoyage du nom pour l'affichage (enlève le mot clé redondant)
            clean_name = col_name.replace(filter_keyword, "").strip(" _-") or col_name
            results.append(f"{clean_name}: {val:,.2f} ({perc:.1f}%)")

        return {
            "analysis_type": f"Pareto (Top Contributeurs) pour '{filter_keyword}'",
            "top_5_items": results,
            "total_scope_value": total_global,
        }

    # ==============================================================================
    # 4. VISUALISATION ASCII & TENDANCE (Compatible Wide Format)
    # ==============================================================================
    def plot_generic_trend(self, filename: str, column_keyword: str) -> dict:
        """Génère un graphique ASCII pour une colonne donnée."""
        path = os.path.join(DATA_FOLDER, filename)
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except:
            return {"error": "Lecture fichier impossible."}

        # Recherche colonne cible
        df_cols_map = {self._smart_normalize(c): c for c in df.columns}
        search_key = self._smart_normalize(column_keyword)
        target = next(
            (real for clean, real in df_cols_map.items() if search_key in clean), None
        )

        if not target:
            return {
                "error": "Colonne introuvable.",
                "available_columns": list(df.columns),
            }

        # Recherche colonne Date
        date_col = next((c for c in df.columns if "date" in c.lower()), None)
        if not date_col:
            # Fallback : prend la 1ère colonne si elle contient "date" ou "mois" ou "année"
            date_col = df.columns[0]

        try:
            df[date_col] = pd.to_datetime(df[date_col], errors="coerce")
            df[target] = pd.to_numeric(df[target], errors="coerce")
            data = df.sort_values(date_col).dropna(subset=[date_col, target])

            # Échantillonnage si trop de points (>24 mois) pour l'affichage
            if len(data) > 24:
                data = data.iloc[:: len(data) // 24]
        except:
            return {"error": "Erreur conversion données (Date/Valeur)."}

        if data.empty:
            return {"error": "Aucune donnée valide."}

        vals = data[target].values
        dates = data[date_col].dt.strftime("%Y-%m").values
        min_v, max_v = np.min(vals), np.max(vals)
        rng = max_v - min_v if max_v != min_v else 1

        chart = [f"TENDANCE VISUELLE : {target}", f"Max: {max_v:,.0f} €"]
        for d, v in zip(dates, vals):
            # Barre max 20 caractères
            bar_len = int(((v - min_v) / rng) * 20)
            bar = "█" * bar_len if bar_len > 0 else "|"
            chart.append(f"{d} : {bar} ({v:,.0f})")
        chart.append(f"Min: {min_v:,.0f} €")

        return {"ascii_plot": "\n".join(chart)}

    def calculate_growth_trend(self, filename: str, column_keyword: str) -> dict:
        """Calcule la variation (%) entre le début et la fin."""
        # (Même logique de chargement/recherche que plot_generic_trend)
        path = os.path.join(DATA_FOLDER, filename)
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except:
            return {"error": "Lecture impossible."}

        df_cols_map = {self._smart_normalize(c): c for c in df.columns}
        target = next(
            (
                real
                for clean, real in df_cols_map.items()
                if self._smart_normalize(column_keyword) in clean
            ),
            None,
        )
        if not target:
            return {"error": "Colonne introuvable.", "available": list(df.columns)}

        date_col = next((c for c in df.columns if "date" in c.lower()), df.columns[0])
        df[date_col] = pd.to_datetime(df[date_col], errors="coerce")
        df[target] = pd.to_numeric(df[target], errors="coerce")
        data = df.sort_values(date_col).dropna(subset=[target])

        if data.empty:
            return {"error": "Données vides."}
        v_start, v_end = data[target].iloc[0], data[target].iloc[-1]

        var = ((v_end - v_start) / abs(v_start)) * 100 if v_start != 0 else 0

        return {
            "metric": target,
            "start_date": str(data[date_col].iloc[0].date()),
            "end_date": str(data[date_col].iloc[-1].date()),
            "start_value": v_start,
            "end_value": v_end,
            "variation_percent": round(var, 2),
            "trend_direction": "Hausse ↗" if var > 0 else "Baisse ↘",
        }

    # ==============================================================================
    # 5. AVANCE : ANOMALIES & CORRELATION
    # ==============================================================================
    def detect_anomalies(
        self, filename: str, column_keyword: str, threshold: float = 2.0
    ) -> dict:
        """Détecte les pics anormaux (Z-Score)."""
        path = os.path.join(DATA_FOLDER, filename)
        try:
            df = (
                pd.read_csv(path, sep=None, engine="python")
                if filename.endswith(".csv")
                else pd.read_excel(path)
            )
        except:
            return {"error": "Lecture."}

        df_cols_map = {self._smart_normalize(c): c for c in df.columns}
        target = next(
            (
                real
                for clean, real in df_cols_map.items()
                if self._smart_normalize(column_keyword) in clean
            ),
            None,
        )
        if not target:
            return {"error": "Colonne introuvable."}

        series = pd.to_numeric(df[target], errors="coerce").dropna()
        if len(series) < 5:
            return {"error": "Pas assez de données pour détecter une anomalie."}

        mean, std = series.mean(), series.std()
        if std == 0:
            return {"result": "Aucune anomalie (valeur constante)."}

        anomalies = []
        date_col = next((c for c in df.columns if "date" in c.lower()), df.columns[0])
        df[date_col] = pd.to_datetime(df[date_col], errors="coerce")
        data = df.dropna(subset=[target]).sort_values(date_col)

        for idx, row in data.iterrows():
            val = row[target]
            z = (val - mean) / std
            if abs(z) > threshold:
                d_str = row[date_col].strftime("%Y-%m")
                anomalies.append(f"{d_str}: {val:,.0f} (Z-Score={z:.1f})")

        return {
            "metric_analyzed": target,
            "anomalies_detected": (
                anomalies
                if anomalies
                else "Rien à signaler (Aucun pic > 2 écarts-types)."
            ),
        }

    def compare_metrics_correlation(
        self, filename: str, col_a_keyword: str, col_b_keyword: str
    ) -> dict:
        """Corrélation entre deux colonnes (ex: Dette vs Recettes)."""
        path = os.path.join(DATA_FOLDER, filename)
        try:
            df = (
                pd.read_csv(path, sep=None, engine="python")
                if filename.endswith(".csv")
                else pd.read_excel(path)
            )
        except:
            return {"error": "Lecture."}

        map_cols = {self._smart_normalize(c): c for c in df.columns}
        real_a = next(
            (
                v
                for k, v in map_cols.items()
                if self._smart_normalize(col_a_keyword) in k
            ),
            None,
        )
        real_b = next(
            (
                v
                for k, v in map_cols.items()
                if self._smart_normalize(col_b_keyword) in k
            ),
            None,
        )

        if not real_a or not real_b:
            return {"error": "Une des colonnes est introuvable."}

        data = df[[real_a, real_b]].apply(pd.to_numeric, errors="coerce").dropna()
        if len(data) < 2:
            return {"error": "Données insuffisantes."}

        corr = data[real_a].corr(data[real_b])
        return {
            "comparison": f"'{real_a}' vs '{real_b}'",
            "correlation_coefficient": round(corr, 2),
            "interpretation": (
                "Forte Corrélation Positive (Elles montent ensemble)"
                if corr > 0.7
                else (
                    "Corrélation Inverse (Opposées)"
                    if corr < -0.7
                    else "Peu ou pas de lien"
                )
            ),
        }

    def forecast_metric_linear(
        self, filename: str, column_keyword: str, months: int = 6
    ) -> dict:
        """Prévision simple sur 6 mois (Régression Linéaire)."""
        path = os.path.join(DATA_FOLDER, filename)
        try:
            df = (
                pd.read_csv(path, sep=None, engine="python")
                if filename.endswith(".csv")
                else pd.read_excel(path)
            )
        except:
            return {"error": "Lecture."}

        map_cols = {self._smart_normalize(c): c for c in df.columns}
        target = next(
            (
                v
                for k, v in map_cols.items()
                if self._smart_normalize(column_keyword) in k
            ),
            None,
        )
        if not target:
            return {"error": "Colonne introuvable."}

        date_col = next((c for c in df.columns if "date" in c.lower()), df.columns[0])
        df[date_col] = pd.to_datetime(df[date_col], errors="coerce")
        df["ordinal"] = df[date_col].map(pd.Timestamp.toordinal)
        df[target] = pd.to_numeric(df[target], errors="coerce")

        data = df.dropna(subset=[target, "ordinal"])
        if len(data) < 5:
            return {"error": "Pas assez de données pour prédire."}

        X = data[["ordinal"]].values
        y = data[target].values

        model = LinearRegression().fit(X, y)

        last_date = data[date_col].max()
        future_dates = [
            last_date + pd.DateOffset(months=i) for i in range(1, months + 1)
        ]
        future_X = [[d.toordinal()] for d in future_dates]
        pred = model.predict(future_X)

        return {
            "forecast_horizon": f"{months} mois",
            "trend_direction": "Hausse" if pred[-1] > y[-1] else "Baisse",
            "predictions": [
                f"{d.strftime('%Y-%m')}: {p:,.0f}" for d, p in zip(future_dates, pred)
            ],
        }
